// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 val, uint256 lockTime, uint256 am) public {
        vm.assume(val > 0);
        vm.assume(lockTime > 0);
        vm.assume(am > 0);
        c.Put{value: am}(lockTime);
        // After Put, MinSum is still 0 because no SetMinSum called
        uint256 minSumBefore = c.MinSum();
        // Try to call Collect with am less than current balance (am was just deposited)
        // The collect will revert because MinSum is 0 and am > 0 so acc.balance >= MinSum is true but am > MinSum false conditional
        // Actually we need to ensure Collect might succeed; set MinSum then revert condition
        // Instead we test the invariant: after any sequence ending in Collect, MinSum remains 0 if SetMinSum was never called
        // Simulate a call to Collect
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", am));
        // Whether Collect reverts or not, MinSum must be unchanged
        uint256 minSumAfter = c.MinSum();
        assertTrue(minSumAfter == minSumBefore);
    }
}

