pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 unlockTime, uint256 putAmount, uint256 collectAmount) public {
        // Bound inputs to avoid overflow
        unlockTime = bound(unlockTime, 0, 1000000);
        putAmount = bound(putAmount, 0, 1000000);
        collectAmount = bound(collectAmount, 0, 1000000);

        // Save initial MinSum
        uint256 initialMinSum = c.MinSum();

        // Ensure we have enough balance for Collect call
        vm.deal(address(this), putAmount);

        // Perform Put
        c.Put{value: putAmount}(unlockTime);

        // Try to perform Collect
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // Rule: If Collect succeeded, MinSum is still the initial value (no change)
        // because SetMinSum can only be called before initialization and only once
        if (success) {
            assertTrue(c.MinSum() == initialMinSum, "MinSum unchanged after Collect");
        }
    }
}

