contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 _am, uint256 _lockTime, uint256 _minSum) public {
        // Bound inputs to reasonable values
        _am = bound(_am, 0, 100 ether);
        _lockTime = bound(_lockTime, 0, 365 days);
        _minSum = bound(_minSum, 0, 100 ether);

        uint256 initialMinSum = c.MinSum();

        // Attempt to call SetMinSum (will revert if initialized)
        (bool setMinSumSuccess, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", _minSum));

        // Call Initialized
        c.Initialized();

        // Give contract some ETH
        vm.deal(address(c), 100 ether);

        // Try Collect
        vm.deal(address(this), 1 ether);
        (bool collectSuccess, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", _am));

        // The rule: if SetMinSum was not called (reverted), then MinSum must still equal its initial value
        assertTrue(!setMinSumSuccess || c.MinSum() != initialMinSum || c.MinSum() == _minSum, "MinSum changed unexpectedly");
    }
}

