pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSum, uint256 _am, uint256 initialBalance) public {
        // Precondition: initialBalance must be ≥ minSum so that the Collect condition can be met, but we want to force a revert when msg.sender balance is insufficient
        // Ensure initialBalance < _am to guarantee Collect reverts (since acc.balance < _am)
        vm.assume(minSum > 0 && _am > initialBalance);
        vm.assume(initialBalance < type(uint256).max);

        // Setup: initialize contract and set MinSum
        vm.prank(address(this));
        c.SetLogFile(address(0));
        c.Initialized();
        c.SetMinSum(minSum);

        // Fund the contract with enough balance for the Collect call to possibly succeed
        vm.deal(address(c), _am);

        // Give msg.sender (test contract) some balance
        vm.deal(address(this), initialBalance);

        // Get MinSum before Collect
        uint256 minSumBefore = c.MinSum();

        // Call Collect with a value that will revert because _am > acc.balance
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", _am));

        // Assert that if call reverts, MinSum unchanged
        if (!success) {
            assertTrue(c.MinSum() == minSumBefore, "MinSum changed after revert");
        }
    }
}

