pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 initialBalance, uint256 minSum, uint256 lockTime, uint256 collectAmount) public {
        // Restrict inputs to reasonable ranges
        vm.assume(caller != address(0));
        vm.assume(initialBalance >= 1e18 && initialBalance <= 1e24);
        vm.assume(minSum >= 1 && minSum <= initialBalance);
        vm.assume(lockTime >= 1 && lockTime <= 365 days);
        vm.assume(collectAmount >= 1 && collectAmount <= initialBalance);

        // Setup: set minSum, fund caller with initialBalance, put funds into contract
        vm.prank(caller);
        c.SetMinSum(minSum);
        vm.deal(caller, initialBalance);
        vm.prank(caller);
        c.Put(lockTime);

        // Record balance before collect
        uint256 balanceBefore = address(caller).balance;

        // Warp to after unlock time
        vm.warp(block.timestamp + lockTime + 1);

        // Call Collect
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // The general rule: if Collect succeeds, caller's balance increases by exactly collectAmount
        if (success) {
            uint256 balanceAfter = address(caller).balance;
            assertTrue(balanceAfter == balanceBefore + collectAmount, "Balance should increase by collectAmount when Collect succeeds");
        }
    }
}

