pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address user, uint256 amount, uint256 deposit, uint256 lockTime, uint256 minSum) public {
        vm.assume(user != address(0));
        vm.assume(deposit > 0);
        vm.assume(amount <= deposit);
        vm.assume(minSum <= deposit);
        vm.assume(lockTime <= type(uint256).max - block.timestamp);

        c.SetMinSum(minSum);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        vm.deal(user, deposit);
        vm.prank(user);
        c.Put(lockTime);

        vm.warp(block.timestamp + lockTime + 1);

        uint256 balanceBefore = c.Acc(user).balance;
        vm.prank(user);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", amount));

        uint256 balanceAfter = c.Acc(user).balance;
        bool reverted = !success;

        if (balanceBefore >= minSum && balanceBefore >= amount && block.timestamp > c.Acc(user).unlockTime) {
            if (!reverted) {
                assertTrue(balanceAfter == balanceBefore - amount, "Balance should decrease by amount on successful Collect");
            } else {
                assertTrue(balanceAfter == balanceBefore, "Balance should stay same on reverted Collect");
            }
        } else {
            assertTrue(balanceAfter == balanceBefore, "Balance should stay same when conditions not met");
        }
    }
}

