    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 am, uint256 unlockTime) public {
        vm.assume(am <= type(uint256).max / 2);
        vm.assume(unlockTime <= type(uint256).max / 2);

        // Set up: initialize, set min sum to 0, and fund the caller
        c.SetMinSum(0);
        c.Initialized();

        address sender = address(0x1234);
        vm.deal(sender, am + 1 ether);
        vm.prank(sender);
        c.Put(unlockTime);

        bool initializedBefore = c.Initialized(); // actually the variable is named intitalized in the contract, but there's no getter; we use the return value of the function? Actually Initialized() is a function that sets it. There is no public view function. We'll check state through another means. The contract has no view getter for Initialized. We'll instead check that the function can be called again (should revert if initialized). So we'll use a try/catch. But the rule must be general. We'll just check that after Collect, calling Initialized() reverts (meaning it was set).

        vm.prank(sender);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", am));

        // Try calling Initialized again - it should revert because already set
        vm.prank(sender);
        (bool initSuccess, ) = address(c).call(abi.encodeWithSignature("Initialized()"));

        // The rule: if Collect succeeded and didn't change the balance, then initializing again should revert
        if (success) {
            // Check that calling Collect again with a small amount still reverts if already initialized
            // Actually the rule: Initialized remains true after any successful Collect call.
            assertTrue(!initSuccess);
        }
    }
}

